output_text:
[
  {
    "id": "take_cart_from_station",
    "text": "A shopper must take a cart from the cart station near the entrance before completing the trip.",
    "abstraction": {
      "state_properties": {
        "cartStation": "at(1,7)"
      },
      "events": {
        "takeCartAtStation": {
          "pre": {
            "and": [
              "cartStation",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeCartAtStation"
    }
  },
  {
    "id": "exit_with_cart",
    "text": "A shopper may not leave the supermarket unless they are still with their cart.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_single_file_aisle",
    "text": "Shopping carts are forbidden in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_single_file_with_cart",
    "text": "A shopper must not enter a single-file aisle while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever a shopper parks or releases a cart, they are obliged to retrieve a cart before leaving.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "wideAisle"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "wideAisle"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "park_only_in_wide_staging_area",
    "text": "Carts may only be parked in wide non-shelf staging areas, not inside shelf aisles or beside shelves.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        },
        "stagingArea": {
          "and": [
            "wideAisle",
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "stagingArea"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_open_shelf_service",
    "text": "Shelf interactions outside single-file aisles must be performed with a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "openShelfAccess": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openShelfAccess",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "interact_only_with_station_cart_or_shelf",
    "text": "Interactions are allowed only when using the entrance cart station, parking or retrieving a cart, or taking an item from an adjacent shelf.",
    "abstraction": {
      "state_properties": {
        "cartStation": "at(1,7)",
        "shelfAccess": "adjShelf"
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": {
              "or": [
                "cartStation",
                "shelfAccess",
                "parkCart",
                "retrieveCart"
              ]
            }
          }
        ]
      }
    }
  }
]
